3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs after {@link AssignOwnerHousehold} (which sets and back-fills the {@code householdId}) and before
9	 * the owner is saved. Sets the owner's {@code householdSize} to the number of members its household has
10	 * after this create: the existing owners already sharing the same {@code householdId} plus this new one
11	 * (not yet persisted). Owners with no household ({@code householdId == null}) are a household of one. The
12	 * value is mutated in place via {@code @Val} so the save/respond steps persist and return it.
13	 */
14	public class CountHouseholdMembers {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = owner.getHouseholdId();
18	        int size = 1; // this owner, not yet persisted
19	        if (householdId != null) {
20	            size += (int) ownerRepository.findAll().stream()
21	                    .filter(existing -> householdId.equals(existing.getHouseholdId()))
22	                    .count();
23	        }
24	        owner.setHouseholdSize(size);
25	    }
26	}
